from collections import deque

def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str):
        return None
    if not path.startswith('/'):
        path = cwd.rstrip('/') + '/' + path if cwd != '/' else '/' + path

    components = deque(path.split('/'))
    current = []  # list of path segments resolved so far
    link_count = 0

    while components:
        comp = components.popleft()
        if comp == '' or comp == '.':
            continue
        elif comp == '..':
            if current:
                current.pop()
        else:
            current.append(comp)
            cur_path = '/' + '/'.join(current)
            if cur_path in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[cur_path]
                # remove the link component itself; it'll be replaced by target resolution
                current.pop()
                if target.startswith('/'):
                    new_components = target.split('/')
                else:
                    dir_path = '/' + '/'.join(current)
                    if dir_path == '/':
                        combined = '/' + target
                    else:
                        combined = dir_path + '/' + target
                    new_components = combined.split('/')
                components.extendleft(reversed(new_components))

    result = '/' + '/'.join(current)
    if result != '/' and result.endswith('/'):
        result = result.rstrip('/')
    return result

